python3 -c "
import pandas as pd
invoices = pd.read_csv('/app/dataset/invoices.csv')

buyers = invoices['buyer_id'].unique()
alternating = []

for b in buyers:
    sellers = invoices[invoices['buyer_id'] == b].sort_values('invoice_date')['seller_id'].tolist()
    if len(sellers) >= 4:
        # Check if they alternate exactly between two
        if len(set(sellers)) == 2:
            is_alt = True
            for i in range(len(sellers)-1):
                if sellers[i] == sellers[i+1]:
                    is_alt = False
                    break
            if is_alt:
                alternating.append(b)

print(f'Found {len(alternating)} alternating buyers:')
print(alternating)
"

